function artifact=aggregateV4BValidationControlled()
root=v4SetupPaths();folder=fullfile(root,'results','validation','track_b','controlled_awgn','B-param-v01','passes');errors=zeros(3,4,3);counts=zeros(4,3);vp=zeros(3,1);falseVp=zeros(3,1);frames=zeros(3,1);passMetrics=zeros(20,3,4);
for i=1:20,x=load(fullfile(folder,sprintf('pass_%02d.mat',i)),'result');r=x.result;errors=errors+r.rawErrors;counts=counts+r.denominators;vp=vp+r.vpAccepted;falseVp=falseVp+r.vpFalseAccepted;frames=frames+r.frames;passMetrics(i,:,:)=r.metrics(:,:,3);end
metrics=zeros(size(errors));for region=1:3,for method=1:3,metrics(method,:,region)=reshape(errors(method,:,region),1,4)./counts(:,region).';end,end;fa=falseVp./vp;coverage=vp./counts(1,:).';qualityPassed=all(fa(1:2)<=0.02&coverage(1:2)>=0.01&vp(1:2)>=200);performance=struct('stageMinusPaperSer',metrics(2,1,3)-metrics(3,1,3),'stageMinusPaperHardBer',metrics(2,2,3)-metrics(3,2,3),'stageMinusPaperMlBer',metrics(2,3,3)-metrics(3,3,3));artifact=struct('status',ternary(qualityPassed,'PASS','FAIL'),'passes',20,'channel','AWGN','mode','controlled-time','rawErrors',errors,'denominators',counts,'metrics',metrics,'vpAccepted',vp,'vpFalseAccepted',falseVp,'vpFalseAcceptance',fa,'vpCoverage',coverage,'qualityGatePassed',qualityPassed,'performance',performance,'passMetrics',passMetrics,'conditionsFrozen',true);out=fileparts(folder);save(fullfile(out,'validation.mat'),'artifact','-v7.3');small=rmfield(artifact,'passMetrics');write(fullfile(out,'validation.json'),jsonencode(small,'PrettyPrint',true));if ~qualityPassed,error('V4:BValidation','B controlled validation quality gate failed.');end
end
function x=ternary(ok,a,b),if ok,x=a;else,x=b;end,end
function write(path,text),f=fopen(path,'w','n','UTF-8');cl=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear cl,end
